-- ============================================================================
-- SEED: enriquece os 6 biomas (silver.bioma, ja seedados sem geometria na V011)
-- com geometria + linhagem, igual a V037 fez pra municipio - sem este seed, o
-- ambiente so tem geometria de bioma depois de alguem disparar a ingestao manual
-- (POST /api/fontes/{id}/executar), o que nao serve pra "subir e ja ter tudo".
--
-- Geometria SIMPLIFICADA (GeometryPrecisionReducer scale=1e5 + 
-- TopologyPreservingSimplifier tolerancia=0.01 grau ~1,1 km) a partir da
-- execucao real desta fonte (lote 61, mesmo hash_conteudo abaixo) - o shapefile
-- oficial do IBGE (escala 1:250.000) pesava ~44 MB de WKT bruto pras 6 geometrias,
-- inviavel versionar; simplificado fica ~480 KB total, sem distorcer area/forma
-- visivelmente numa tela de mapa nacional. Bonus: a simplificacao tambem corrige
-- as auto-intersecoes que SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT achava na
-- geometria original bruta (nao usar essa geometria original pra calculo fino
-- de area/interseccao sem revalidar - esta aqui e pra exibicao, nao pra IRL/ICV).
-- ============================================================================

INSERT INTO ${controleSchema}.lote_ingestao
    (fonte_dado_id, origem_referencia, hash_conteudo, quantidade_registros, status, data_execucao)
SELECT id, 'http://geoftp.ibge.gov.br/informacoes_ambientais/estudos_ambientais/biomas/vetores/2025_Biomas-e-Sistema-Costeiro-Marinho-do-Brasil-1-250000_shp.zip', '4df89767be4145f5a1d2e40aaa71d450ae00d055155565b50cd356cc866f6cac', 6, 'PROMOVIDO_SILVER', SYSTIMESTAMP
  FROM ${controleSchema}.fonte_dado
 WHERE nome = 'IBGE - Limites de biomas';

