-- PANTANAL (18067 bytes de WKT)
DECLARE
    l_wkt   CLOB;
    l_fonte NUMBER;
    l_lote  NUMBER;
    l_bruto NUMBER;
    l_bioma NUMBER;
BEGIN
    SELECT id INTO l_fonte FROM ${controleSchema}.fonte_dado WHERE nome = 'IBGE - Limites de biomas';
    SELECT id INTO l_lote FROM ${controleSchema}.lote_ingestao
     WHERE fonte_dado_id = l_fonte AND hash_conteudo = '4df89767be4145f5a1d2e40aaa71d450ae00d055155565b50cd356cc866f6cac';
